def new(slug,rank,amount,url,summary,**kw):
 d=dict(private_rank=rank,tuition_usd=amount,tuition_status='verified',tuition_year='2026-2027',tuition_source_url=url,tuition_verified_on='2026-10-20',tuition_basis='Annual full-time day tuition before aid; grade 12',cost_basis='day',cost_status='exact',mandatory_annual_fees_usd=0,mandatory_household_annual_fees_usd=0,fees_complete=True,required_fee_total_unresolved=False,evidence_summary=summary)
 d.update(kw);out['private:'+slug]=d
